/* vNN.xx, UI REDESIGN ui5q2i (his #50, from the AAA judge of the stash shot): THE BELT SPANS THE PANEL. The nine tactical belt keys
   on the stash were capped at 76px each (v18.98), so at 1080p the row stopped about 120px short of the loadout panel edge and sat
   left-heavy under the backpack grid. The cap is gone: the nine keys share the whole width and stay square. */
#root #hub #hotplanwrap [data-plan]{ max-width:none; }
/* vNN.xx, UI REDESIGN ui5q1c (his #50, from the AAA judge

check:
{v:'VER',what:'his #50 (UI redesign ui5q2i): the nine tactical belt keys on the stash share the whole loadout width (no 76px cap per key)',
 run:function(){
   if(!(window.__station&&window.__hubEnter)) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], q, row, last, gap;
   try{
     __topClear(); __hubEnter(); __station('term','KeyE');
     q=document.querySelectorAll('#hub #hotplanwrap [data-plan]');
     if(q.length<9) return 'SKIP: the stash drew '+q.length+' belt keys';
     if(getComputedStyle(q[0]).maxWidth!=='none') bad.push('a belt key is capped at '+getComputedStyle(q[0]).maxWidth);
     last=q[q.length-1]; row=last.parentNode;
     if(last.getClientRects().length&&row.getClientRects().length){
       gap=row.getBoundingClientRect().right-last.getBoundingClientRect().right;
       if(gap>8) bad.push('the belt stops '+Math.round(gap)+'px short of its row');
     }
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
